"""This file contains a Class for starting the Integrated Console (IC) electron apps using
Selenium WebDriver Manager and chromedriver. The chromedriver can be provided as a binary
executable for OFFLINE use, or obtained from ChromeDriverManager for ONLINE use.
"""

import os
from selenium import webdriver
from selenium.webdriver.chrome.service import Service
from webdriver_manager.chrome import ChromeDriverManager
from requests.exceptions import ConnectionError
from selenium.common.exceptions import WebDriverException, SessionNotCreatedException
from interops.libraries.desktop.configuration import Config

class ChromeBrowser:

    def __init__(self) -> None:

        # Get the webdriver config file path for the current working directory
        _driverconfig_path = os.path.abspath(
            os.path.join(os.getcwd(), os.path.dirname(__file__), "webdriverconfig.cfg"))

        # Load the webdriverconfig.cfg file
        Config.load(_driverconfig_path)

        self._binary_location = Config.get("binary_locations.ic_console_electron_app_path",
                                     "C:/Program Files/tsm-console-desktop/tsm-console-desktop.exe")

        # Note: _chromedriver_path specifies the location of the chromedriver binary.
        # It is for OFFLINE use and is not used with ChromeDriverManager (ONLINE use)
        self._chromedriver_path = Config.get("binary_locations.chromedriver_path",
                                     "C:/Users/ccpadmin/Desktop/SolVer_Automation/chromedriver.exe")
        self._chromedriver_version = "116.0.5845.96" # Note: IC electron app versions 4.38 require this version of chromedriver

    @property
    def chromedriver_version(self):
        return self._chromedriver_version

    @chromedriver_version.setter
    def chromedriver_version(self, chromedriver_version: str):
        self._chromedriver_version = chromedriver_version

    @property
    def binary_location(self):
        return self._binary_location

    @binary_location.setter
    def binary_location(self, binary_location: str):
        if os.path.isfile(binary_location):
            self._binary_location = binary_location
        else:
            raise ValueError("Cannot find binary location, check path is in Unix format")

    @classmethod
    def web_driver(cls):
        return cls()

    @classmethod
    def electron_driver(cls, new_binary_location: str):
        electron_driver_cls = cls()
        if new_binary_location:
            electron_driver_cls.binary_location = new_binary_location
        return electron_driver_cls

    @classmethod
    def tsm_monitor_driver(cls):
        monitor_driver_cls = cls()
        monitor_driver_cls.binary_location = Config.get("binary_locations.ic_monitor_electron_app_path",
                                                        "C:/Program Files/tsm-monitor-desktop/tsm-monitor-desktop.exe")
        return monitor_driver_cls

    @classmethod
    def tsm_console_driver(cls):
        console_driver_cls = cls()
        console_driver_cls.binary_location = Config.get("binary_locations.ic_console_electron_app_path",
                                                        "C:/Program Files/tsm-console-desktop/tsm-console-desktop.exe")
        return console_driver_cls

    def create_driver(self, debug_port: int, binary: bool = False, headless: bool = False, offline_chromedriver: bool = False, debuggerAddress: str = "", user_data_dir: str = ""):
        def launch_driver(_service: Service, _options: webdriver.ChromeOptions):
            try:
                return webdriver.Chrome(service = _service, options = _options)
            except SessionNotCreatedException as e:
                print("SessionNotCreatedException Error: " + str(e))
                raise SessionNotCreatedException(
                    "ChromeDriver session not created. Please check the ChromeDriver version is compatible with the electron app")
            except WebDriverException:
                raise WebDriverException(
                    "Failed to find chromedriver exe file. Please check this path has been specified in the webdriverconfig.cfg file")
            except Exception as e:
                # Catch all other exceptions
                print("Failed to create Chrome Driver: " + str(e))

        _option = webdriver.ChromeOptions()
        _option.set_capability("goog:loggingPrefs",{"performance": "ALL"})
        _option.add_experimental_option("windowTypes", ["webview"])
        # Update debugging port
        _option.add_argument(f"remote-debugging-port={debug_port}")
        if user_data_dir:
            _option.add_argument(rf"user-data-dir={user_data_dir}")
        if binary:
            _option.binary_location=self._binary_location
        if headless:
            _option.add_argument("--headless")
        if debuggerAddress:
            _option.add_experimental_option("debuggerAddress", debuggerAddress)
        else:
            # cannot add excludeSwitches once debuggerAddress is set, see https://stackoverflow.com/questions/63091842
            _option.add_experimental_option("excludeSwitches",["enable-logging"])

        if offline_chromedriver:
            _service = Service(executable_path=self._chromedriver_path)
        else:
            # Using ChromeDriverManager (requires internet access)
            try:
                _service = Service(ChromeDriverManager(driver_version=self._chromedriver_version).install())
            except ConnectionError as e:
                print("Error using ChromeDriverManager, please check internet connection: " + str(e))
                print("Try using offline ChromeDriver instead...")
                _service = Service(executable_path=self._chromedriver_path)

        return launch_driver(_service, _option)

    def create_web_driver(self, target_ip: str, debug_port: int, binary: bool = False, headless: bool = False):
        def launch_web_driver(target_ip: str, _options: webdriver.ChromeOptions):
            try:
                return webdriver.Remote(command_executor=target_ip, options = _options)
            except SessionNotCreatedException as e:
                print("SessionNotCreatedException Error: " + str(e))
                raise SessionNotCreatedException(
                    "ChromeDriver session not created. Please check the ChromeDriver version is compatible with the electron app")
            except WebDriverException:
                raise WebDriverException(
                    "Failed to find chromedriver exe file. Please check this path has been specified in the webdriverconfig.cfg file")
            except Exception as e:
                # Catch all other exceptions
                print("Failed to create Chrome Driver: " + str(e))

        _option = webdriver.ChromeOptions()
        _option.set_capability("goog:loggingPrefs",{"performance": "ALL"})
        _option.add_experimental_option("excludeSwitches",["enable-logging"])
        _option.add_experimental_option("windowTypes", ["webview"])
        # Update debugging port
        _option.add_argument(f"remote-debugging-port={debug_port}")
        if binary:
            _option.binary_location=self._binary_location
        if headless:
            _option.add_argument("--headless")

        return launch_web_driver(target_ip, _option)

if __name__ == '__main__':
    tsm_console = ChromeBrowser.tsm_console_driver().create_driver(debug_port = 9222, binary=True)
    tsm_monitor = ChromeBrowser.tsm_monitor_driver().create_driver(debug_port = 8756, binary=True)
    tsm_console.quit()
    tsm_monitor.quit()
